CREATE POLICY "Site Survey files are readable by visit access" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'site-survey-attachments' AND split_part(name, '/', 1) ~ '^[0-9a-f-]{36}$' AND public.can_view_site_survey_visit(split_part(name, '/', 1)::uuid, auth.uid()));
CREATE POLICY "Site Survey files are uploadable by executors" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-survey-attachments' AND owner_id = auth.uid()::text AND split_part(name, '/', 1) ~ '^[0-9a-f-]{36}$' AND public.can_view_site_survey_visit(split_part(name, '/', 1)::uuid, auth.uid()) AND public.has_site_survey_permission(auth.uid(), 'site_survey_executar'));
CREATE POLICY "Site Survey files are removable by uploader or editors" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-survey-attachments' AND split_part(name, '/', 1) ~ '^[0-9a-f-]{36}$' AND public.can_view_site_survey_visit(split_part(name, '/', 1)::uuid, auth.uid()) AND (owner_id = auth.uid()::text OR public.has_site_survey_permission(auth.uid(), 'site_survey_editar')));